parameters.content:
INPUT CONTRACT (pass these fields when calling this workflow):
{
  correlation_id, event_id, action_id, tool_id,
  description, parameters, credential_ref, destination,
  estimated_cost, records_affected, reversible,
  verification_method, rollback_method, requesting_agent,
  expires_minutes (default 2880 = 48h)
}
OUTPUT: { approved: true|false, reason, action_hash }

parameters.jsCode:
const crypto = require('crypto');
const input = $json;

const tool_id = input.tool_id || 'unknown.tool';
const destination = input.destination || '';
const estimated_cost = Number(input.estimated_cost || 0);
const credential_ref = input.credential_ref || null;

// --- classify action per blueprint Section 9 table ---
let action_class = 'internal_write';
if (tool_id.includes('read') || tool_id.includes('get') || tool_id.includes('search')) {
  action_class = 'read_only';
} else if (tool_id.includes('gmail') || tool_id.includes('email') || tool_id.includes('sms') || tool_id.includes('post_public') || tool_id.includes('customer')) {
  action_class = 'external_comm';
} else if (tool_id.includes('pay') || tool_id.includes('quote') || tool_id.includes('purchase') || tool_id.includes('subscription')) {
  action_class = 'spending';
} else if (tool_id.includes('credential') || tool_id.includes('rotate') || tool_id.includes('permission')) {
  action_class = 'credential_change';
} else if (tool_id.includes('deploy') || tool_id.includes('publish') || tool_id.includes('schema')) {
  action_class = 'production_change';
} else if (tool_id.includes('delete') || tool_id.includes('cancel') || tool_id.includes('overwrite')) {
  action_class = 'destructive';
}

// --- deterministic decision ---
let decision = 'allow';
let policy_id = 'POL-READONLY-001';
let reason = 'Read-only or low-sensitivity action, auto-allowed with audit.';

if (action_class === 'internal_write') {
  decision = 'allow';
  policy_id = 'POL-INTERNAL-001';
  reason = 'Internal reversible write within existing scoped role.';
} else if (action_class === 'external_comm') {
  decision = 'require_approval';
  policy_id = 'POL-EXTCOMM-001';
  reason = 'External communication requires Dominique approval unless a narrow preapproved template/recipient rule exists.';
} else if (['spending','credential_change','production_change','destructive'].includes(action_class)) {
  decision = 'require_approval';
  policy_id = 'POL-HIGHRISK-001';
  reason = `${action_class} always requires Dominique approval per policy.`;
} else if (action_class === 'physical' || action_class === 'emergency') {
  decision = 'require_approval';
  policy_id = 'POL-PHYSICAL-001';
  reason = 'Physical or emergency action requires separate safety gate and Dominique approval.';
}

// explicit override: caller can force approval
if (input.requires_approval === true) {
  decision = 'require_approval';
  policy_id = 'POL-CALLER-FLAG-001';
  reason = 'Caller explicitly flagged this action as requiring approval.';
}

// --- action hash (binds approval to exact parameters) ---
const canonical = JSON.stringify({ tool_id, parameters: input.parameters || {} });
const action_hash = crypto.createHash('sha256').update(canonical).digest('hex');

return {
  ...input,
  action_class,
  decision,
  policy_id,
  reason,
  action_hash,
  expires_minutes: input.expires_minutes || 2880
};

const base = 'https://shopify-automation-n8n.onrender.com';
const execId = $execution.id;
const hash = $json.action_hash;
const approveUrl = `${base}/webhook-waiting/${execId}?decision=approve&hash=${hash}`;
const denyUrl = `${base}/webhook-waiting/${execId}?decision=deny&hash=${hash}`;
return { ...$json, approveUrl, denyUrl };

