parameters.jsCode:
const q = $json.query || {};
const storedHash = $('Build Approval Links').first().json.action_hash;
const hashOk = q.hash === storedHash;
const status = q.decision === 'approve' && hashOk ? 'approved' : 'denied';
const reason = !hashOk ? 'action_hash mismatch - parameters changed since approval request, rejected' : (q.decision === 'approve' ? 'Approved by Dominique' : 'Denied by Dominique or expired with no response');
return { approved: status === 'approved', status, decided_at: new Date().toISOString(), reason, action_hash: storedHash };

const original = $('Deterministic Policy Gate').first().json;
const minutes = Number(original.expires_minutes || 2880);
const expiresAt = new Date(Date.now() + minutes * 60 * 1000).toISOString();
return { ...original, policy_decision_id: $json.policy_decision_id, expires_at: expiresAt };
